// archivo: inventoryservice.cs
// función: contiene la lógica de negocio relacionada con entradas, salidas y control del stock.

using AbarrotesInventory.Application.Interfaces; using AbarrotesInventory.Domain.Entities;
// espacio de nombres que organiza las clases del proyecto.
namespace AbarrotesInventory.Application.Services;
// clase principal de este archivo.
public class InventoryService(IUnitOfWork u) : IInventoryService {
 public async Task<List<Product>> GetProductsAsync()=>await u.Products.ListAsync(); public async Task<Product?> GetProductAsync(int id)=>await u.Products.GetAsync(id); public async Task SaveProductAsync(Product p){if(p.Id==0) await u.Products.AddAsync(p); else u.Products.Update(p); await u.SaveAsync();} public async Task DeleteProductAsync(int id){var p=await u.Products.GetAsync(id);if(p!=null){p.Active=false;u.Products.Update(p);await u.SaveAsync();}} public Task<List<Category>> GetCategoriesAsync()=>u.Categories.ListAsync(); public Task<List<Supplier>> GetSuppliersAsync()=>u.Suppliers.ListAsync(); public Task<List<Customer>> GetCustomersAsync()=>u.Customers.ListAsync(); public async Task<DashboardDto> DashboardAsync(){var ps=await u.Products.ListAsync();var cs=await u.Categories.ListAsync();var ss=await u.Suppliers.ListAsync();var cus=await u.Customers.ListAsync();var sales=await u.Sales.ListAsync();var purchases=await u.Purchases.ListAsync();var d=DateTime.Today;return new(ps.Count(x=>x.Active),ps.Count(x=>x.Active&&x.Stock<=x.MinStock),cs.Count(x=>x.Active),ss.Count(x=>x.Active),cus.Count(x=>x.Active),sales.Where(x=>x.Date.Date==d).Sum(x=>x.Total),purchases.Where(x=>x.Date.Date==d).Sum(x=>x.Total));} public async Task RegisterSaleAsync(Sale s){foreach(var d in s.Details){var p=await u.Products.GetAsync(d.ProductId)??throw new Exception("Producto no existe");if(p.Stock<d.Quantity)throw new Exception($"Stock insuficiente: {p.Name}");var before=p.Stock;p.Stock-=d.Quantity;u.Products.Update(p);await u.Movements.AddAsync(new InventoryMovement{ProductId=p.Id,Type="SALE",Quantity=d.Quantity,StockBefore=before,StockAfter=p.Stock,Reference=s.Number});d.Subtotal=d.Quantity*d.UnitPrice;}s.Subtotal=s.Details.Sum(x=>x.Subtotal);s.Total=s.Subtotal+s.Tax;await u.Sales.AddAsync(s); await u.SaveAsync();} public async Task RegisterPurchaseAsync(Purchase p){foreach(var d in p.Details){var pr=await u.Products.GetAsync(d.ProductId)??throw new Exception("Producto no existe");var before=pr.Stock;pr.Stock+=d.Quantity;pr.PurchasePrice=d.UnitCost;u.Products.Update(pr);d.Subtotal=d.Quantity*d.UnitCost;await u.Movements.AddAsync(new InventoryMovement{ProductId=pr.Id,Type="PURCHASE",Quantity=d.Quantity,StockBefore=before,StockAfter=pr.Stock,Reference=p.Number});}p.Total=p.Details.Sum(x=>x.Subtotal);await u.Purchases.AddAsync(p);await u.SaveAsync();}}
